        LocalDateTime actual = localDateTime.minusDays(2146963456);
        
        LocalDateTime expected = ((LocalDateTime) createInstance("org.joda.time.LocalDateTime"));
        setField(expected, "org.joda.time.LocalDateTime", "iLocalMillis", 737670970L);
